"""Stream original BGRA source-camera frames to lossless FFV1 Matroska.

One writer per named source camera. Caller joins Native sensor frame IDs before
writing and closes every encoder before marking the capture sealed.
"""

import subprocess
from pathlib import Path


class FFV1Writer:
    def __init__(self, path: Path, width: int, height: int, fps: int = 20):
        path = Path(path)
        if path.exists() or width <= 0 or height <= 0 or fps <= 0:
            raise ValueError("Fresh path and positive video dimensions/rate required")
        self.path, self.width, self.height, self.fps = path, width, height, fps
        self.frames = 0
        self.process = subprocess.Popen([
            "ffmpeg", "-hide_banner", "-loglevel", "error", "-n",
            "-f", "rawvideo", "-pixel_format", "bgra",
            "-video_size", f"{width}x{height}", "-framerate", str(fps),
            "-i", "pipe:0", "-an", "-c:v", "ffv1", "-level", "3",
            "-pix_fmt", "bgr0", str(path)],
            stdin=subprocess.PIPE, stderr=subprocess.PIPE)

    def write(self, bgra: bytes):
        if not isinstance(bgra, bytes) or len(bgra) != self.width * self.height * 4:
            raise ValueError("Native BGRA frame size mismatch")
        if self.process.poll() is not None:
            raise ValueError("Video encoder exited before source closure")
        self.process.stdin.write(bgra)
        self.frames += 1

    def close(self):
        if self.process.stdin and not self.process.stdin.closed:
            self.process.stdin.close()
        code = self.process.wait(timeout=60)
        error = self.process.stderr.read().decode(errors="replace")
        self.process.stderr.close()
        if code != 0 or self.frames == 0 or not self.path.is_file():
            raise ValueError("FFV1 source encoder failed: " + error[-1000:])
        return {"path": str(self.path), "frames": self.frames,
                "width": self.width, "height": self.height, "fps": self.fps,
                "encoding": "ffv1-lossless"}

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

"""Four named source-camera actor construction at the pinned CPU profile.

Callers supply source-grounded static transforms for overview/approach/corner
and a relative driver transform. Real pixel coverage must be audited after run.
"""

from contextlib import contextmanager


SIZES = {"overview": (1920, 1080), "approach": (1280, 720),
         "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


@contextmanager
def source_cameras(world, ego, transforms):
    if set(transforms) != set(SIZES):
        raise ValueError("All four named source-camera transforms required")
    sensors = {}
    try:
        for name, (width, height) in SIZES.items():
            blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
            blueprint.set_attribute("image_size_x", str(width))
            blueprint.set_attribute("image_size_y", str(height))
            blueprint.set_attribute("fov", "90")
            blueprint.set_attribute("sensor_tick", "0.05")
            kwargs = {"attach_to": ego} if name == "driver_reference" else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError("Native camera spawn failed: " + name)
            sensors[name] = sensor
        yield sensors
    finally:
        for sensor in reversed(list(sensors.values())):
            sensor.stop()
            sensor.destroy()

"""Select an unbranched Native lane corridor from source-reviewed road IDs.

The selected IDs and alley/access-aisle classification must be independently
source-reviewed. This helper verifies lane continuity and measured route length;
it does not declare public-way status or guarantee 80 mph is physically attained.
"""

import math


def _distance(a, b):
    return math.hypot(a.x - b.x, a.y - b.y)


def select_corridor(native_map, starts, *, reviewed_road_id, reviewed_lane_id,
                    minimum_length_m, step_m=5.0):
    if not isinstance(reviewed_road_id, int) or not isinstance(reviewed_lane_id, int):
        raise ValueError("Source-reviewed Native road and lane IDs required")
    if not math.isfinite(minimum_length_m) or minimum_length_m <= 0 or not math.isfinite(step_m) or step_m <= 0:
        raise ValueError("Positive finite engineering corridor lengths required")
    candidates = []
    for start in starts:
        waypoint = native_map.get_waypoint(start.location, project_to_road=False)
        if waypoint is None or waypoint.road_id != reviewed_road_id or waypoint.lane_id != reviewed_lane_id or waypoint.is_junction:
            continue
        path = [waypoint]
        length = 0.0
        for _ in range(math.ceil(minimum_length_m / step_m) + 10):
            successors = [wp for wp in path[-1].next(step_m)
                          if wp.road_id == reviewed_road_id and wp.lane_id == reviewed_lane_id and not wp.is_junction]
            if len(successors) != 1:
                break
            next_wp = successors[0]
            segment = _distance(path[-1].transform.location, next_wp.transform.location)
            if not math.isfinite(segment) or segment <= 0:
                break
            length += segment
            path.append(next_wp)
            if length >= minimum_length_m:
                candidates.append({"start": start, "waypoints": path,
                                   "measured_length_m": length,
                                   "road_id": reviewed_road_id,
                                   "lane_id": reviewed_lane_id})
                break
    if not candidates:
        raise ValueError("No source-reviewed Native corridor meets requested length")
    return max(candidates, key=lambda candidate: candidate["measured_length_m"])

"""Native vehicle speed request with bounded throttle/brake and measured feedback.

The controller targets speed cases; the saved trace, not its target, establishes
the measured rate. At 80 mph an alley may be physically infeasible or unsafe;
the route finder must verify an actual long, unobstructed candidate before use.
"""

import math


MPH_TO_MPS = 0.44704


class SpeedController:
    def __init__(self, target_mph, control_factory, *, gain=0.12):
        if not isinstance(target_mph, (int, float)) or isinstance(target_mph, bool) or not math.isfinite(target_mph) or target_mph <= 0:
            raise ValueError("Positive finite target mph required")
        if not callable(control_factory) or gain <= 0:
            raise ValueError("Control factory and positive gain required")
        self.target_mps = target_mph * MPH_TO_MPS
        self.control_factory = control_factory
        self.gain = gain

    def step(self, vehicle, *, distance_to_route_end_m, steering=0.0):
        velocity = vehicle.get_velocity()
        speed = math.sqrt(velocity.x**2 + velocity.y**2 + velocity.z**2)
        if not math.isfinite(speed) or not math.isfinite(distance_to_route_end_m) or distance_to_route_end_m < 0:
            raise ValueError("Finite measured speed and route clearance required")
        if not math.isfinite(steering) or abs(steering) > 1:
            raise ValueError("Invalid steering request")
        # This is engineering braking, not a legal stopping-distance claim.
        stopping_allowance = speed * speed / (2 * 4.0) + 8.0
        if distance_to_route_end_m <= stopping_allowance:
            throttle, brake = 0.0, 1.0
        else:
            error = self.target_mps - speed
            throttle = min(1.0, max(0.0, self.gain * error))
            brake = min(1.0, max(0.0, -self.gain * error))
        command = self.control_factory(throttle=throttle, brake=brake, steer=steering)
        vehicle.apply_control(command)
        return {"measured_speed_mps": speed, "target_speed_mps": self.target_mps,
                "distance_to_route_end_m": distance_to_route_end_m,
                "throttle": throttle, "brake": brake, "steer": steering}

"""Source-bound sampled speed measurements for NRS 484B.600(1)(e).

The exact statutory boundary is 80 mph. A sampled maximum cannot establish a
between-sample maximum or the legal character of the road/vehicle operation.
"""

import hashlib
import json
import math
from pathlib import Path


MPH_TO_MPS = 0.44704
BOUNDARY_MPS = 80 * MPH_TO_MPS
REQUIRED = ("subject_motion.jsonl", "video_frames.jsonl", "road_context.json")


def _number(value, label):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError("Missing finite " + label)
    return float(value)


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def analyze(root: Path) -> dict:
    root = Path(root)
    sources = {}
    for name in REQUIRED:
        path = root / name
        if not path.is_file():
            raise ValueError("Missing required source: " + name)
        sources[name] = hashlib.sha256(path.read_bytes()).hexdigest()
    context = json.loads((root / "road_context.json").read_text())
    for key in ("native_map_id", "subject_actor_id", "subject_blueprint_id",
                "route_source", "alley_source", "access_aisle_source"):
        if not context.get(key):
            raise ValueError("Missing Native subject/road context: " + key)
    motion, frames = _rows(root / "subject_motion.jsonl"), _rows(root / "video_frames.jsonl")
    if len(motion) < 2 or len(motion) != len(frames):
        raise ValueError("Incomplete motion/frame history")
    previous = (-1, -math.inf)
    samples = []
    for index, (row, frame) in enumerate(zip(motion, frames)):
        fid, time = row.get("frame"), _number(row.get("time_s"), "time")
        if type(fid) is not int or fid <= previous[0] or time <= previous[1]:
            raise ValueError("Nonmonotone original motion history")
        previous = (fid, time)
        if frame.get("video_frame") != index or frame.get("carla_frame") != fid or frame.get("time_s") != time:
            raise ValueError("Original frame/time join failed")
        if row.get("subject_actor_id") != context["subject_actor_id"] or row.get("speed_source") != "actor.get_velocity":
            raise ValueError("Subject identity or original velocity source mismatch")
        velocity = row.get("velocity_mps")
        if not isinstance(velocity, list) or len(velocity) != 3:
            raise ValueError("Missing complete Native velocity")
        xyz = [_number(value, "velocity component") for value in velocity]
        speed_mps = math.sqrt(sum(value * value for value in xyz))
        if "speed_mps" in row and abs(_number(row["speed_mps"], "speed") - speed_mps) > 1e-5:
            raise ValueError("Reported speed and Native velocity disagree")
        samples.append({"frame": fid, "time_s": time, "speed_mps": speed_mps,
                        "speed_mph": speed_mps / MPH_TO_MPS})
    peak = max(samples, key=lambda sample: sample["speed_mps"])
    return {"format": "worker-absolute-speed-samples", "sources": sources,
            "subject_actor_id": context["subject_actor_id"],
            "statutory_boundary_mps": BOUNDARY_MPS, "statutory_boundary_mph": 80.0,
            "peak_sample": peak,
            "sampled_peak_greater_than_80_mph": peak["speed_mps"] > BOUNDARY_MPS,
            "samples": samples,
            "between_sample_peak": "unresolved",
            "road_public_way_judgment": "unresolved",
            "legal_conclusion": "unresolved"}

"""Independent, saved-source audit of the three 80 mph comparison cases.

This checks comparison isolation and source integrity. It never declares a legal
outcome from a requested speed or a sampled maximum.
"""

import argparse
import hashlib
import json
import math
from pathlib import Path

from speed_measurements import analyze


SUFFIXES = ("source_verified_below_80", "source_verified_at_80", "source_verified_above_80")
CAMERAS = ("overview.mkv", "approach.mkv", "reference_corner.mkv", "driver_reference.mkv")
FIXED_CONFIG = ("law_id", "cell_id", "actor", "duration_s", "fps", "camera_plan", "weather")
FIXED_CONTEXT = ("native_map_id", "road_id", "lane_id", "route_source", "alley_source",
                 "access_aisle_source", "road_authority_source", "subject_blueprint_id")


def _read(path):
    if not path.is_file():
        raise ValueError("Missing comparison source: " + str(path))
    return json.loads(path.read_text())


def _hash(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def audit(attempts):
    if len(attempts) != 3:
        raise ValueError("Exactly three comparison attempts required")
    records = []
    for attempt in map(Path, attempts):
        config = _read(attempt / "config.json")
        context = _read(attempt / "road_context.json")
        case_id = config.get("selected_case_id", "")
        if not any(case_id.endswith("__" + suffix) for suffix in SUFFIXES):
            raise ValueError("Unexpected exact comparison case: " + str(case_id))
        for name in FIXED_CONFIG:
            if config.get(name) is None:
                raise ValueError("Missing fixed config condition: " + name)
        for name in FIXED_CONTEXT:
            if context.get(name) is None:
                raise ValueError("Missing fixed road condition: " + name)
        if config["fps"] != 20 or config["duration_s"] <= 0:
            raise ValueError("Invalid common capture contract")
        target = config.get("requested_speed_mph")
        if isinstance(target, bool) or not isinstance(target, (int, float)) or not math.isfinite(target):
            raise ValueError("Missing finite requested speed")
        source_hashes = {}
        for camera in CAMERAS:
            path = attempt / camera
            if not path.is_file() or not path.stat().st_size:
                raise ValueError("Missing source camera: " + camera)
            source_hashes[camera] = _hash(path)
        report = analyze(attempt)
        source_hashes.update(report["sources"])
        records.append({"case_id": case_id, "target_mph": float(target),
                        "sampled_peak_mph": report["peak_sample"]["speed_mph"],
                        "sampled_peak_over_80": report["sampled_peak_greater_than_80_mph"],
                        "fixed_config": {name: config[name] for name in FIXED_CONFIG},
                        "fixed_context": {name: context[name] for name in FIXED_CONTEXT},
                        "sources": source_hashes})
    by_suffix = {}
    for record in records:
        suffix = next(s for s in SUFFIXES if record["case_id"].endswith("__" + s))
        if suffix in by_suffix:
            raise ValueError("Duplicate comparison case: " + suffix)
        by_suffix[suffix] = record
    if set(by_suffix) != set(SUFFIXES):
        raise ValueError("Missing comparison case")
    ordered = [by_suffix[s] for s in SUFFIXES]
    prefixes = {r["case_id"].rsplit("__", 1)[0] for r in ordered}
    if len(prefixes) != 1:
        raise ValueError("Mixed assignment comparison")
    for name in ("fixed_config", "fixed_context"):
        if any(r[name] != ordered[0][name] for r in ordered[1:]):
            raise ValueError("Comparison fixed conditions differ: " + name)
    targets = [r["target_mph"] for r in ordered]
    if not (targets[0] < 80 == targets[1] < targets[2]):
        raise ValueError("Requested speed comparison does not bracket 80 mph")
    return {"format": "worker-speed-comparison-audit", "comparison_id": "absolute_80_mph_boundary",
            "case_ids": [r["case_id"] for r in ordered], "records": ordered,
            "fixed_conditions_checked": list(FIXED_CONFIG) + list(FIXED_CONTEXT),
            "deliberate_difference": "requested speed target across exact 80 mph boundary",
            "between_sample_peak": "unresolved", "legal_conclusion": "unresolved"}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--attempt", action="append", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    receipt = audit(args.attempt)
    Path(args.output).write_text(json.dumps(receipt, indent=2, allow_nan=False) + "\n")


if __name__ == "__main__":
    main()

"""Independent CPU audit of original C10301 speed and four-camera sources.

A positive result means source closure and software decode passed. It is not a
physical completion, public-highway, or legal acceptance decision.
"""
import hashlib
import json
import math
from pathlib import Path

CAMERAS=('overview.mkv','approach.mkv','reference_corner.mkv','driver_reference.mkv')

def _sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def _rows(path):return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]

def audit(attempt:Path,case_id:str,media_auditor=None)->dict:
    attempt=Path(attempt)
    if media_auditor is None:
        from worker_exchange.media import audit as media_auditor
    config_path=attempt/'config.json';result_path=attempt/'result.json'
    for path in (config_path,result_path,attempt/'subject_motion.jsonl',attempt/'video_frames.jsonl',attempt/'trace.jsonl',attempt/'capture/evidence.jsonl',*(attempt/name for name in CAMERAS)):
        if not path.is_file():raise ValueError('Missing original source: '+str(path.relative_to(attempt)))
    config=json.loads(config_path.read_text());result=json.loads(result_path.read_text())
    if config.get('selected_case_id')!=case_id or result.get('case_id')!=case_id:raise ValueError('Case identity mismatch')
    if sorted(result.get('video_references',[]))!=sorted(CAMERAS):raise ValueError('Four source cameras not bound in result')
    motion,mapping,trace=_rows(attempt/'subject_motion.jsonl'),_rows(attempt/'video_frames.jsonl'),_rows(attempt/'trace.jsonl')
    if not motion or len(motion)!=len(mapping) or len(trace)!=len(mapping):raise ValueError('Incomplete original frame streams')
    prev=(-1,-math.inf);speeds=[]
    for i,(m,f,t) in enumerate(zip(motion,mapping,trace)):
        frame,time=m.get('frame'),m.get('time_s')
        if type(frame) is not int or type(time) not in (int,float) or not math.isfinite(time) or frame<=prev[0] or time<=prev[1]:
            raise ValueError('Nonmonotone original motion')
        prev=frame,time
        if f.get('video_frame')!=i or f.get('carla_frame')!=frame or f.get('time_s')!=time or t.get('frame')!=frame or t.get('time_s')!=time:
            raise ValueError('Original frame join mismatch')
        xyz=m.get('velocity_mps')
        if m.get('speed_source')!='actor.get_velocity' or not isinstance(xyz,list) or len(xyz)!=3 or any(type(v) not in (int,float) or not math.isfinite(v) for v in xyz):
            raise ValueError('Original Native velocity missing')
        speed=math.sqrt(sum(v*v for v in xyz))
        if abs(speed-m.get('speed_mps',float('nan')))>1e-6 or abs(speed-t.get('speed_mps',float('nan')))>1e-6:
            raise ValueError('Original speed disagrees with velocity')
        speeds.append(speed)
    peak=max(speeds)/0.44704
    measured=result.get('measured_values',{}).get('sampled_peak_speed_mph')
    if type(measured) not in (int,float) or not math.isfinite(measured) or abs(peak-measured)>1e-4:
        raise ValueError('Finalized peak speed differs from original velocity')
    for name in ('subject_motion.jsonl','video_frames.jsonl','road_context.json'):
        evidence=result.get('recording_evidence',{})
        hashes=result.get('source_hashes', evidence.get('source_hashes',{}) if isinstance(evidence,dict) else {})
        expected=hashes.get(name)
        if not expected or _sha(attempt/name)!=expected:raise ValueError('Original source hash mismatch: '+name)
    evidence=result.get('recording_evidence',{})
    capture_sha=result.get('capture_evidence_sha256', evidence.get('capture_evidence_sha256') if isinstance(evidence,dict) else None)
    if _sha(attempt/'capture/evidence.jsonl')!=capture_sha:
        raise ValueError('Capture evidence hash mismatch')
    receipts={}
    for name in CAMERAS:
        receipts[name]=media_auditor(attempt/name,len(mapping),mapping_sha256=_sha(attempt/'video_frames.jsonl'))
        if not receipts[name].get('passed',True):raise ValueError('Source camera decode failed: '+name)
    return {'format':'worker-c10301-source-audit','case_id':case_id,'source_frame_count':len(mapping),
            'sampled_peak_speed_mph':peak,'original_sources_sha256':{name:_sha(attempt/name) for name in CAMERAS},
            'camera_decode_receipts':receipts,'source_integrity_passed':True,
            'physical_acceptance_claimed':False,'legal_acceptance_claimed':False}

